Use one SystemVerilog module with the exact interface. All state updates on rising clk. rst is synchronous, active high, and has priority. No other modules, file I/O, delays, or simulation-only behavior in the DUT.","interface":{"top":"signed_saturating_add","ports":[{"name":"clk","direction":"input","width":1,"signed":false},{"name":"rst","direction":"input","width":1,"signed":false},{"name":"a","direction":"input","width":8,"signed":true},{"name":"b","direction":"input","width":8,"signed":true},{"name":"sum","direction":"output","width":8,"signed":true}]},"constraints":"SystemVerilog; xczu3eg-sbva484-1-e; post-synthesis clock clk at 5 ns; simulation seed 1."},"current":{"revision_id":"154dceff-74d8-43e6-b258-f8ef9a89eca1","source_sha256":"761f3df58a9b0f4eaf0b6cee70cec7b8aa21a1edaece5ee1e6c0f178eb941ea1","source":"module signed_saturating_add(
    input  logic               clk,
    input  logic               rst,
    input  logic signed [7:0]  a,
    input  logic signed [7:0]  b,
    output logic signed [7:0]  sum
);

    wire signed [8:0] sum_ext = {a[7], a} + {b[7], b};

    always @(posedge clk) begin
        if (rst)
            sum <= 8'sd0;
        else if (sum_ext > 9'sd127)
            sum <= 8'sd127;
        else if (sum_ext < -9'sd128)
            sum <= -8'sd128;
        else
            sum <= sum_ext[7:0];
    end

endmodule
